import React from "react";
import MainMenu from "../components/mainMenu";
import Footer from "../components/footer";
import Container from "../components/container";

const SinkholePage = () => {
  return (
    <>
      <MainMenu activePage="sinkhole" />
      <Container>
        <div className="py-20">
          <h1 className="text-4xl font-bold mb-8 text-gray-900 border-b-4 border-blue-500 pb-2 inline-block">
            Sinkhole Documentation
          </h1>
          
          <section className="mb-12">
            <h2 className="text-2xl font-semibold mb-4 text-blue-600">What is Sinkhole?</h2>
            <p className="text-lg text-gray-700 leading-relaxed">
              Sinkhole is a lightweight, secure synchronization bridge between Android devices and Google Drive. 
              It allows you to keep your local mobile folders in sync with the cloud without the need for complex server setups.
            </p>
          </section>

          <section className="mb-12">
            <h2 className="text-2xl font-semibold mb-4 text-blue-600">The Obsidian Use Case</h2>
            <p className="text-lg text-gray-700 leading-relaxed">
              For users of Obsidian, Sinkhole serves as a free, reliable alternative to Obsidian Sync. 
              By bridging the gap between Android's Storage Access Framework (SAF) and Google Drive, 
              it allows you to synchronize your Obsidian vaults across devices using your existing Google account.
            </p>
          </section>

          <section className="mb-12">
            <h2 className="text-2xl font-semibold mb-4 text-blue-600">Step-by-Step Guide</h2>
            <div className="bg-gray-50 p-8 rounded-lg shadow-inner">
              <ol className="list-decimal list-inside space-y-4 text-lg text-gray-700">
                <li><span className="font-semibold">Install the APK:</span> Download and install the Sinkhole application on your Android device.</li>
                <li><span className="font-semibold">Select a Local Folder:</span> Grant Storage Access Framework (SAF) permissions and choose the folder you wish to sync (e.g., your Obsidian vault).</li>
                <li><span className="font-semibold">Authenticate:</span> Sign in with your Google account using secure OAuth authentication.</li>
                <li><span className="font-semibold">Initial Sync:</span> Perform your first synchronization to upload or download files.</li>
                <li><span className="font-semibold">Desktop Access:</span> Your files are now available on your desktop via Google Drive, ensuring your data is always within reach.</li>
              </ol>
            </div>
          </section>
        </div>
      </Container>
      <Footer />
    </>
  );
};

export default SinkholePage;
